<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Renderer { private Api_Client $api; public function __construct() { $this->api = new Api_Client(); } public function register( array $options = [] ): string { wp_enqueue_style( 'cfair-public' ); $options += [ 'language' => 'auto', 'layout' => 'cards', 'search' => true, 'filters' => true, 'per_page' => 12 ]; $params = [ 'language' => $options['language'], 'page' => max( 1, absint( $_GET['cfair_page'] ?? 1 ) ), 'per_page' => $options['per_page'], 'search' => sanitize_text_field( wp_unslash( $_GET['cfair_search'] ?? '' ) ), 'risk_tier' => sanitize_key( $_GET['cfair_risk'] ?? '' ), 'status' => sanitize_key( $_GET['cfair_status'] ?? '' ) ]; $result = $this->api->get_systems( $params ); ob_start(); cfair_template( 'register.php', compact( 'result', 'options', 'params' ) ); return (string) ob_get_clean(); } public function system( string $reference, string $language = 'auto' ): string { wp_enqueue_style( 'cfair-public' ); if ( ! preg_match( '/^[A-Za-z0-9_-]{1,80}$/', $reference ) ) return ''; $result = $this->api->get_system( $reference ); ob_start(); cfair_template( 'system.php', compact( 'result', 'reference' ) ); return (string) ob_get_clean(); } }
